// Accessible, deep-linkable tabs. Panels stay in the DOM (hidden attr) so crawlers index every industry/feature section.
(function(){
  function setup(container){
    var tabs = container.querySelectorAll('[role="tab"]');
    var panels = container.querySelectorAll('[role="tabpanel"]');
    function activate(tab, push){
      tabs.forEach(function(t){ t.setAttribute('aria-selected', t===tab ? 'true':'false'); t.tabIndex = t===tab ? 0 : -1; });
      panels.forEach(function(p){ p.hidden = (p.id !== tab.getAttribute('aria-controls')); });
      if(push && history.replaceState){ history.replaceState(null,'','#'+tab.getAttribute('aria-controls')); }
    }
    tabs.forEach(function(t,i){
      t.addEventListener('click', function(){ activate(t,true); });
      t.addEventListener('keydown', function(e){
        var k=e.key, n=null;
        if(k==='ArrowRight'||k==='ArrowDown'){ n=tabs[(i+1)%tabs.length]; }
        if(k==='ArrowLeft'||k==='ArrowUp'){ n=tabs[(i-1+tabs.length)%tabs.length]; }
        if(k==='Home'){ n=tabs[0]; } if(k==='End'){ n=tabs[tabs.length-1]; }
        if(n){ e.preventDefault(); n.focus(); activate(n,true); }
      });
    });
    container._activateById = function(id){
      var tab = container.querySelector('[aria-controls="'+id+'"]');
      if(tab){ activate(tab,false); return true; } return false;
    };
    activate(container.querySelector('[role="tab"][aria-selected="true"]')||tabs[0], false);
  }
  var containers = document.querySelectorAll('[data-tabs]');
  containers.forEach(setup);
  function openFromHash(){
    var id = location.hash.replace('#','');
    if(!id) return;
    containers.forEach(function(c){ if(c._activateById(id)){ var el=document.getElementById(id); if(el){ setTimeout(function(){ c.scrollIntoView({behavior:'smooth',block:'start'}); },50); } } });
  }
  window.addEventListener('hashchange', openFromHash);
  openFromHash();
  // Pills and in-page links that target a panel should switch the tab instead of jumping to hidden content
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(){
      var id=a.getAttribute('href').slice(1);
      containers.forEach(function(c){ c._activateById(id); });
    });
  });
})();

